package embeds

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

// Generated files, relative to the repository root.
const (
	JSONPath       = "pipeline/pipeline/generated/embeds.json"
	TypeScriptPath = "src/api/embeds.generated.ts"
	RustPath       = "collaboration-rs/crates/notes/src/catalog.rs"
)

const generatedBy = "Generated by server/cmd/openapi from server/internal/embeds. Do not edit manually."

func indented() ([]byte, error) {
	var out bytes.Buffer
	enc := json.NewEncoder(&out)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(Get()); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

// JSON is the catalog for the pipeline.
func JSON() ([]byte, error) { return indented() }

// TypeScript is the catalog for the browser, typed by its literal values.
func TypeScript() ([]byte, error) {
	body, err := indented()
	if err != nil {
		return nil, err
	}
	var out bytes.Buffer
	fmt.Fprintf(&out, "// %s\n", generatedBy)
	out.WriteString("export const EMBED_CATALOG = ")
	out.Write(bytes.TrimRight(body, "\n"))
	out.WriteString(" as const;\n")
	return out.Bytes(), nil
}

// rustFloat names the bounds the collaboration server compares as numbers
// from JSON (f64); every other limit is a count or a length (usize).
var rustFloat = map[string]bool{
	"QUESTION_GRAPH_DIMENSION_MIN": true,
	"QUESTION_GRAPH_DIMENSION_MAX": true,
	"QUESTION_IMAGE_DIMENSION_MAX": true,
	"QUESTION_MARKS_MAX":           true,
}

// Rust is the catalog for the collaboration server (crate notes).
func Rust() []byte {
	var out bytes.Buffer
	fmt.Fprintf(&out, "//! %s\n//! The embed catalog (todo-embeds.md): element types, embed kinds,\n", generatedBy)
	out.WriteString("//! material kinds and shared limits.\n\n")
	fmt.Fprintf(&out, "pub const VERSION: u32 = %d;\n\n", Version)

	for _, l := range Limits() {
		if rustFloat[l.Name] {
			fmt.Fprintf(&out, "pub const %s: f64 = %d.0;\n", l.Name, l.Value)
		} else {
			fmt.Fprintf(&out, "pub const %s: usize = %d;\n", l.Name, l.Value)
		}
	}

	out.WriteString(`
/// One element type a material document may hold.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Element {
    pub name: &'static str,
    pub void: bool,
    pub inline: bool,
    /// Only stored as a top-level block.
    pub top_level: bool,
    /// Keys required besides ` + "`type`" + ` and ` + "`children`" + `.
    pub required: &'static [&'static str],
    /// The closed key set, when the element has one.
    pub fields: Option<&'static [&'static str]>,
    pub forbidden: &'static [&'static str],
    /// Keys held as shared text in a room, so typing merges.
    pub shared_text: &'static [&'static str],
    /// Paths naming editor assets (` + "`[]`" + ` walks a list).
    pub assets: &'static [&'static str],
    pub resizable: bool,
    /// Element children, in order, when fixed.
    pub children: &'static [&'static str],
    /// Material kinds whose documents may hold it.
    pub materials: &'static [&'static str],
}

/// One rich block kind and its name in each layer.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Embed {
    pub kind: &'static str,
    /// ` + "`value`, `live_source` or `item`" + `.
    pub class: &'static str,
    /// The node type a note holds it as (` + "`material_ref`" + ` for an item).
    pub element: &'static str,
    pub fence_lang: &'static str,
    /// ` + "`json`, `yaml` or `text`" + `.
    pub fence_body: &'static str,
    /// The chat (OpenUI) component; empty when chat has none.
    pub chat: &'static str,
    /// Material kinds that hold one as their whole document.
    pub materials: &'static [&'static str],
    pub question_block: bool,
    pub question_media: bool,
}

/// One kind of material row.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MaterialKind {
    pub kind: &'static str,
    /// The element its document must hold.
    pub requires: Option<&'static str>,
    /// Edited in its own item rooms; a note embeds it through a ` + "`material_ref`" + `.
    pub item: bool,
}

pub const ELEMENTS: &[Element] = &[
`)
	for _, e := range Elements() {
		fields := "None"
		if e.Fields != nil {
			fields = "Some(" + rustStrs(e.Fields) + ")"
		}
		fmt.Fprintf(&out, `    Element {
        name: %q,
        void: %t,
        inline: %t,
        top_level: %t,
        required: %s,
        fields: %s,
        forbidden: %s,
        shared_text: %s,
        assets: %s,
        resizable: %t,
        children: %s,
        materials: %s,
    },
`, e.Type, e.Void, e.Inline, e.TopLevel, rustStrs(e.Required), fields, rustStrs(e.Forbidden),
			rustStrs(e.SharedText), rustStrs(e.Assets), e.Resizable, rustStrs(e.Children), rustStrs(e.Materials))
	}
	out.WriteString("];\n\npub const EMBEDS: &[Embed] = &[\n")
	for _, e := range Embeds() {
		fmt.Fprintf(&out, `    Embed {
        kind: %q,
        class: %q,
        element: %q,
        fence_lang: %q,
        fence_body: %q,
        chat: %q,
        materials: %s,
        question_block: %t,
        question_media: %t,
    },
`, e.Kind, e.Class, e.Element, e.Fence.Lang, e.Fence.Body, e.Chat, rustStrs(e.Materials),
			e.QuestionBlock, e.QuestionMedia)
	}
	out.WriteString("];\n\npub const MATERIAL_KINDS: &[MaterialKind] = &[\n")
	for _, k := range MaterialKinds() {
		requires := "None"
		if k.Requires != "" {
			requires = fmt.Sprintf("Some(%q)", k.Requires)
		}
		fmt.Fprintf(&out, "    MaterialKind {\n        kind: %q,\n        requires: %s,\n        item: %t,\n    },\n",
			k.Kind, requires, k.Item)
	}
	out.WriteString(`];

/// The element of type ` + "`name`" + `, if the catalog lists it.
pub fn element(name: &str) -> Option<&'static Element> {
    ELEMENTS.iter().find(|e| e.name == name)
}

/// The embed kind ` + "`kind`" + `, if the catalog lists it.
pub fn embed(kind: &str) -> Option<&'static Embed> {
    EMBEDS.iter().find(|e| e.kind == kind)
}

/// The material kind ` + "`kind`" + `, if the catalog lists it.
pub fn material_kind(kind: &str) -> Option<&'static MaterialKind> {
    MATERIAL_KINDS.iter().find(|k| k.kind == kind)
}
`)
	return out.Bytes()
}

func rustStrs(values []string) string {
	if len(values) == 0 {
		return "&[]"
	}
	quoted := make([]string, len(values))
	for i, v := range values {
		quoted[i] = fmt.Sprintf("%q", v)
	}
	return "&[" + strings.Join(quoted, ", ") + "]"
}
